# Evaluates f(f(t)+t) + f(f(t)), the combined value of the two nested branches of f
def f(x):
    return x**2 + 2*x + 3

t = int(input())
if 0 <= t <= 10:
    print((f(f(t)+t) + f(f(t))))
else:
    print("Input out of range. Please enter a number between 0 and 10.")

